-- FINANCIA Phase 2 — household and ledger foundation
-- Generated by: supabase migration new phase2_household_ledger_foundation
-- Target PostgreSQL: 17
-- Target Supabase project: tjutcenodmowkfviwrpd
-- No secrets or user-specific UUIDs are embedded in this migration.

BEGIN;

CREATE SCHEMA IF NOT EXISTS private;
REVOKE ALL ON SCHEMA private FROM PUBLIC;
GRANT USAGE ON SCHEMA private TO authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Identity and single-household boundary
-- ---------------------------------------------------------------------------

CREATE TABLE public.households (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  singleton_key smallint NOT NULL DEFAULT 1,
  name text NOT NULL DEFAULT 'Keluarga',
  base_currency char(3) NOT NULL DEFAULT 'IDR',
  timezone text NOT NULL DEFAULT 'Asia/Jakarta',
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT households_singleton_key_check CHECK (singleton_key = 1),
  CONSTRAINT households_singleton_key_unique UNIQUE (singleton_key),
  CONSTRAINT households_id_pair_unique UNIQUE (id)
);

CREATE TABLE public.profiles (
  user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE RESTRICT,
  display_name text NOT NULL CHECK (char_length(display_name) BETWEEN 1 AND 80),
  avatar_path text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.household_members (
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  user_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE RESTRICT,
  person_key text NOT NULL CHECK (person_key IN ('husband', 'wife')),
  membership_status text NOT NULL DEFAULT 'invited'
    CHECK (membership_status IN ('invited', 'active', 'suspended')),
  invited_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  joined_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (household_id, user_id),
  CONSTRAINT household_members_user_unique UNIQUE (user_id),
  CONSTRAINT household_members_person_unique UNIQUE (household_id, person_key),
  CONSTRAINT household_members_pair_unique UNIQUE (household_id, user_id)
);

CREATE INDEX household_members_household_status_idx
  ON public.household_members (household_id, membership_status);

-- Authorization helpers are deliberately outside the exposed API schema.
CREATE OR REPLACE FUNCTION private.is_household_member(p_household_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.household_members AS hm
    WHERE hm.household_id = p_household_id
      AND hm.user_id = (SELECT auth.uid())
      AND hm.membership_status = 'active'
  );
$function$;

CREATE OR REPLACE FUNCTION private.can_view_profile(p_user_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.household_members AS current_member
    JOIN public.household_members AS target_member
      ON target_member.household_id = current_member.household_id
    WHERE current_member.user_id = (SELECT auth.uid())
      AND current_member.membership_status = 'active'
      AND target_member.user_id = p_user_id
      AND target_member.membership_status IN ('active', 'invited')
  );
$function$;

REVOKE ALL ON FUNCTION private.is_household_member(uuid) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION private.can_view_profile(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION private.is_household_member(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION private.can_view_profile(uuid) TO authenticated;

-- Create an application profile for every Auth identity. Metadata is used only
-- as a display-name hint; it is never used for authorization or household roles.
CREATE OR REPLACE FUNCTION private.handle_auth_user_created()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE
  v_display_name text;
BEGIN
  v_display_name :=
    COALESCE(
      NULLIF(NEW.raw_user_meta_data ->> 'full_name', ''),
      NULLIF(split_part(COALESCE(NEW.email, ''), '@', 1), ''),
      'Pengguna'
    );

  INSERT INTO public.profiles (user_id, display_name)
  VALUES (NEW.id, v_display_name)
  ON CONFLICT (user_id) DO NOTHING;

  RETURN NEW;
END;
$function$;

REVOKE ALL ON FUNCTION private.handle_auth_user_created() FROM PUBLIC, anon, authenticated;

CREATE TRIGGER financia_create_profile_after_auth_user
AFTER INSERT ON auth.users
FOR EACH ROW
EXECUTE FUNCTION private.handle_auth_user_created();

-- ---------------------------------------------------------------------------
-- Chart of Accounts, financial accounts, categories, and transactions
-- ---------------------------------------------------------------------------

CREATE TABLE public.ledger_accounts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  account_code text NOT NULL,
  account_name text NOT NULL,
  account_class text NOT NULL
    CHECK (account_class IN ('asset', 'liability', 'equity', 'income', 'expense')),
  normal_side text NOT NULL CHECK (normal_side IN ('debit', 'credit')),
  parent_account_id uuid,
  is_system boolean NOT NULL DEFAULT false,
  is_postable boolean NOT NULL DEFAULT true,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ledger_accounts_code_unique UNIQUE (household_id, account_code),
  CONSTRAINT ledger_accounts_pair_unique UNIQUE (household_id, id),
  CONSTRAINT ledger_accounts_parent_fk
    FOREIGN KEY (household_id, parent_account_id)
    REFERENCES public.ledger_accounts (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT ledger_accounts_no_self_parent
    CHECK (parent_account_id IS NULL OR parent_account_id <> id)
);

CREATE INDEX ledger_accounts_household_class_idx
  ON public.ledger_accounts (household_id, account_class, is_active);

CREATE TABLE public.transaction_categories (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  category_key text,
  category_name text NOT NULL,
  category_type text NOT NULL CHECK (category_type IN ('income', 'expense')),
  parent_category_id uuid,
  is_system boolean NOT NULL DEFAULT false,
  is_active boolean NOT NULL DEFAULT true,
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT transaction_categories_pair_unique UNIQUE (household_id, id),
  CONSTRAINT transaction_categories_parent_fk
    FOREIGN KEY (household_id, parent_category_id)
    REFERENCES public.transaction_categories (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT transaction_categories_name_unique
    UNIQUE (household_id, category_type, category_name),
  CONSTRAINT transaction_categories_key_unique
    UNIQUE (household_id, category_key)
);

CREATE TABLE public.transactions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  transaction_type text NOT NULL CHECK (
    transaction_type IN (
      'income',
      'expense',
      'transfer',
      'asset_purchase',
      'asset_sale',
      'liability_incurred',
      'liability_payment',
      'business_purchase',
      'business_sale',
      'business_expense',
      'owner_withdrawal',
      'opening_balance',
      'adjustment'
    )
  ),
  category_id uuid,
  owner_attribution text NOT NULL
    CHECK (owner_attribution IN ('husband', 'wife', 'shared')),
  occurred_at timestamptz NOT NULL,
  description text NOT NULL CHECK (char_length(description) BETWEEN 1 AND 240),
  notes text,
  status text NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft', 'posted', 'voided')),
  created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  voided_at timestamptz,
  voided_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  CONSTRAINT transactions_pair_unique UNIQUE (household_id, id),
  CONSTRAINT transactions_category_fk
    FOREIGN KEY (household_id, category_id)
    REFERENCES public.transaction_categories (household_id, id)
    ON DELETE RESTRICT
);

CREATE INDEX transactions_household_occurred_idx
  ON public.transactions (household_id, occurred_at DESC);
CREATE INDEX transactions_household_type_occurred_idx
  ON public.transactions (household_id, transaction_type, occurred_at DESC);
CREATE INDEX transactions_household_status_idx
  ON public.transactions (household_id, status);

CREATE TABLE public.financial_accounts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  ledger_account_id uuid NOT NULL,
  account_name text NOT NULL,
  account_type text NOT NULL
    CHECK (account_type IN ('bank', 'e_wallet', 'cash', 'deposit', 'other')),
  provider_name text,
  owner_attribution text NOT NULL
    CHECK (owner_attribution IN ('husband', 'wife', 'shared')),
  account_number_last4 char(4),
  currency_code char(3) NOT NULL DEFAULT 'IDR',
  opening_balance_amount numeric(20,2) NOT NULL DEFAULT 0
    CHECK (opening_balance_amount >= 0),
  opening_balance_at timestamptz NOT NULL,
  opening_balance_transaction_id uuid,
  is_active boolean NOT NULL DEFAULT true,
  created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT financial_accounts_pair_unique UNIQUE (household_id, id),
  CONSTRAINT financial_accounts_ledger_unique UNIQUE (household_id, ledger_account_id),
  CONSTRAINT financial_accounts_ledger_fk
    FOREIGN KEY (household_id, ledger_account_id)
    REFERENCES public.ledger_accounts (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT financial_accounts_opening_transaction_fk
    FOREIGN KEY (household_id, opening_balance_transaction_id)
    REFERENCES public.transactions (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT financial_accounts_opening_transaction_unique
    UNIQUE (opening_balance_transaction_id)
);

CREATE INDEX financial_accounts_household_owner_idx
  ON public.financial_accounts (household_id, owner_attribution, is_active);

-- ---------------------------------------------------------------------------
-- Double-entry journal
-- ---------------------------------------------------------------------------

CREATE TABLE public.journal_entries (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  transaction_id uuid NOT NULL UNIQUE,
  entry_date date NOT NULL,
  memo text,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'posted')),
  reversal_of_entry_id uuid,
  posted_at timestamptz,
  posted_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT journal_entries_pair_unique UNIQUE (household_id, id),
  CONSTRAINT journal_entries_transaction_fk
    FOREIGN KEY (household_id, transaction_id)
    REFERENCES public.transactions (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT journal_entries_reversal_fk
    FOREIGN KEY (household_id, reversal_of_entry_id)
    REFERENCES public.journal_entries (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT journal_entries_no_self_reversal
    CHECK (reversal_of_entry_id IS NULL OR reversal_of_entry_id <> id),
  CONSTRAINT journal_entries_one_reversal UNIQUE (reversal_of_entry_id)
);

CREATE INDEX journal_entries_household_date_idx
  ON public.journal_entries (household_id, entry_date DESC);

CREATE TABLE public.journal_lines (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE RESTRICT,
  journal_entry_id uuid NOT NULL,
  line_number integer NOT NULL CHECK (line_number > 0),
  ledger_account_id uuid NOT NULL,
  financial_account_id uuid,
  category_id uuid,
  debit_amount numeric(20,2) NOT NULL DEFAULT 0 CHECK (debit_amount >= 0),
  credit_amount numeric(20,2) NOT NULL DEFAULT 0 CHECK (credit_amount >= 0),
  description text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT journal_lines_pair_unique UNIQUE (household_id, id),
  CONSTRAINT journal_lines_number_unique UNIQUE (journal_entry_id, line_number),
  CONSTRAINT journal_lines_one_side_only CHECK (
    (debit_amount > 0 AND credit_amount = 0)
    OR
    (credit_amount > 0 AND debit_amount = 0)
  ),
  CONSTRAINT journal_lines_entry_fk
    FOREIGN KEY (household_id, journal_entry_id)
    REFERENCES public.journal_entries (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT journal_lines_ledger_account_fk
    FOREIGN KEY (household_id, ledger_account_id)
    REFERENCES public.ledger_accounts (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT journal_lines_financial_account_fk
    FOREIGN KEY (household_id, financial_account_id)
    REFERENCES public.financial_accounts (household_id, id)
    ON DELETE RESTRICT,
  CONSTRAINT journal_lines_category_fk
    FOREIGN KEY (household_id, category_id)
    REFERENCES public.transaction_categories (household_id, id)
    ON DELETE RESTRICT
);

CREATE INDEX journal_lines_household_account_idx
  ON public.journal_lines (household_id, ledger_account_id);
CREATE INDEX journal_lines_household_financial_account_idx
  ON public.journal_lines (household_id, financial_account_id)
  WHERE financial_account_id IS NOT NULL;
CREATE INDEX journal_lines_entry_idx
  ON public.journal_lines (journal_entry_id, line_number);

-- ---------------------------------------------------------------------------
-- Lifecycle and accounting integrity triggers
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION private.set_updated_at()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $function$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION private.guard_transaction_lifecycle()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'Transactions must be created as draft';
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION 'Only draft transactions may be edited';
    END IF;

    IF NEW.status = 'posted' AND NOT EXISTS (
      SELECT 1
      FROM public.journal_entries AS je
      WHERE je.household_id = NEW.household_id
        AND je.transaction_id = NEW.id
        AND je.status = 'posted'
    ) THEN
      RAISE EXCEPTION 'A transaction can be posted only after its journal entry is posted';
    END IF;

    IF NEW.status = 'voided' AND EXISTS (
      SELECT 1
      FROM public.journal_entries AS je
      WHERE je.household_id = NEW.household_id
        AND je.transaction_id = NEW.id
    ) THEN
      RAISE EXCEPTION 'Delete the draft journal entry before voiding the transaction';
    END IF;

    NEW.updated_at := now();
    NEW.updated_by := COALESCE((SELECT auth.uid()), NEW.updated_by);
    IF NEW.status = 'voided' THEN
      NEW.voided_at := COALESCE(NEW.voided_at, now());
      NEW.voided_by := COALESCE((SELECT auth.uid()), NEW.voided_by);
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION 'Only draft transactions may be deleted';
    END IF;
    IF EXISTS (
      SELECT 1
      FROM public.journal_entries AS je
      WHERE je.household_id = OLD.household_id
        AND je.transaction_id = OLD.id
    ) THEN
      RAISE EXCEPTION 'Delete the draft journal entry before deleting the transaction';
    END IF;
    RETURN OLD;
  END IF;

  RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION private.guard_journal_entry()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $function$
DECLARE
  v_line_count bigint;
  v_total_debit numeric(20,2);
  v_total_credit numeric(20,2);
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'Journal entries must be created as draft';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.transactions AS t
      WHERE t.household_id = NEW.household_id
        AND t.id = NEW.transaction_id
        AND t.status = 'draft'
    ) THEN
      RAISE EXCEPTION 'A journal entry must reference a draft transaction';
    END IF;

    IF NEW.reversal_of_entry_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM public.journal_entries AS original_entry
      WHERE original_entry.household_id = NEW.household_id
        AND original_entry.id = NEW.reversal_of_entry_id
        AND original_entry.status = 'posted'
    ) THEN
      RAISE EXCEPTION 'A reversal must reference an already posted entry';
    END IF;

    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.status = 'posted' THEN
      RAISE EXCEPTION 'Posted journal entries are immutable';
    END IF;
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.status = 'posted' THEN
      RAISE EXCEPTION 'Posted journal entries are immutable';
    END IF;

    IF NEW.household_id IS DISTINCT FROM OLD.household_id
       OR NEW.transaction_id IS DISTINCT FROM OLD.transaction_id
       OR NEW.reversal_of_entry_id IS DISTINCT FROM OLD.reversal_of_entry_id THEN
      RAISE EXCEPTION 'Journal entry identity and reversal link are immutable';
    END IF;

    IF OLD.status = 'draft' AND NEW.status = 'posted' THEN
      SELECT
        count(*),
        COALESCE(sum(jl.debit_amount), 0),
        COALESCE(sum(jl.credit_amount), 0)
      INTO v_line_count, v_total_debit, v_total_credit
      FROM public.journal_lines AS jl
      WHERE jl.household_id = NEW.household_id
        AND jl.journal_entry_id = NEW.id;

      IF v_line_count < 2 THEN
        RAISE EXCEPTION 'A posted journal entry requires at least two lines';
      END IF;

      IF v_total_debit <= 0 OR v_total_debit <> v_total_credit THEN
        RAISE EXCEPTION
          'Unbalanced journal: debit %, credit %',
          v_total_debit, v_total_credit;
      END IF;

      NEW.posted_at := COALESCE(NEW.posted_at, now());
      NEW.posted_by := COALESCE((SELECT auth.uid()), NEW.posted_by);
    ELSIF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'Invalid journal entry status transition';
    END IF;

    RETURN NEW;
  END IF;

  RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION private.guard_journal_line()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $function$
DECLARE
  v_entry_status text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT je.status INTO v_entry_status
    FROM public.journal_entries AS je
    WHERE je.household_id = NEW.household_id
      AND je.id = NEW.journal_entry_id;

    IF v_entry_status IS DISTINCT FROM 'draft' THEN
      RAISE EXCEPTION 'Journal lines can be inserted only into a draft journal entry';
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    SELECT je.status INTO v_entry_status
    FROM public.journal_entries AS je
    WHERE je.household_id = OLD.household_id
      AND je.id = OLD.journal_entry_id;

    IF v_entry_status IS DISTINCT FROM 'draft' THEN
      RAISE EXCEPTION 'Posted journal lines are immutable';
    END IF;

    SELECT je.status INTO v_entry_status
    FROM public.journal_entries AS je
    WHERE je.household_id = NEW.household_id
      AND je.id = NEW.journal_entry_id;

    IF v_entry_status IS DISTINCT FROM 'draft' THEN
      RAISE EXCEPTION 'Journal lines can be moved only to a draft journal entry';
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    SELECT je.status INTO v_entry_status
    FROM public.journal_entries AS je
    WHERE je.household_id = OLD.household_id
      AND je.id = OLD.journal_entry_id;

    IF v_entry_status IS DISTINCT FROM 'draft' THEN
      RAISE EXCEPTION 'Posted journal lines are immutable';
    END IF;
    RETURN OLD;
  END IF;

  RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION private.sync_transaction_after_journal_post()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $function$
BEGIN
  IF OLD.status = 'draft' AND NEW.status = 'posted' THEN
    UPDATE public.transactions
    SET status = 'posted',
        updated_at = now(),
        updated_by = COALESCE((SELECT auth.uid()), updated_by)
    WHERE household_id = NEW.household_id
      AND id = NEW.transaction_id
      AND status = 'draft';

    IF NOT FOUND THEN
      RAISE EXCEPTION 'The linked transaction could not be moved to posted';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;

CREATE TRIGGER households_set_updated_at
BEFORE UPDATE ON public.households
FOR EACH ROW EXECUTE FUNCTION private.set_updated_at();

CREATE TRIGGER profiles_set_updated_at
BEFORE UPDATE ON public.profiles
FOR EACH ROW EXECUTE FUNCTION private.set_updated_at();

CREATE TRIGGER transactions_guard_lifecycle
BEFORE INSERT OR UPDATE OR DELETE ON public.transactions
FOR EACH ROW EXECUTE FUNCTION private.guard_transaction_lifecycle();

CREATE TRIGGER transactions_set_updated_at
BEFORE UPDATE ON public.transactions
FOR EACH ROW EXECUTE FUNCTION private.set_updated_at();

CREATE TRIGGER journal_entries_guard
BEFORE INSERT OR UPDATE OR DELETE ON public.journal_entries
FOR EACH ROW EXECUTE FUNCTION private.guard_journal_entry();

CREATE TRIGGER journal_entries_sync_transaction
AFTER UPDATE OF status ON public.journal_entries
FOR EACH ROW EXECUTE FUNCTION private.sync_transaction_after_journal_post();

CREATE TRIGGER journal_lines_guard
BEFORE INSERT OR UPDATE OR DELETE ON public.journal_lines
FOR EACH ROW EXECUTE FUNCTION private.guard_journal_line();

-- ---------------------------------------------------------------------------
-- Row Level Security: enable explicitly even though the project has an
-- automatic RLS event trigger. These statements make the migration portable.
-- ---------------------------------------------------------------------------

ALTER TABLE public.households ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.household_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ledger_accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.transaction_categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.transactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.financial_accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.journal_entries ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.journal_lines ENABLE ROW LEVEL SECURITY;

CREATE POLICY households_member_select
ON public.households
FOR SELECT TO authenticated
USING (private.is_household_member(id));

CREATE POLICY households_member_update
ON public.households
FOR UPDATE TO authenticated
USING (private.is_household_member(id))
WITH CHECK (private.is_household_member(id));

CREATE POLICY profiles_household_select
ON public.profiles
FOR SELECT TO authenticated
USING (private.can_view_profile(user_id));

CREATE POLICY profiles_self_update
ON public.profiles
FOR UPDATE TO authenticated
USING (user_id = (SELECT auth.uid()))
WITH CHECK (user_id = (SELECT auth.uid()));

CREATE POLICY household_members_household_select
ON public.household_members
FOR SELECT TO authenticated
USING (private.is_household_member(household_id));

CREATE POLICY ledger_accounts_member_all
ON public.ledger_accounts
FOR ALL TO authenticated
USING (private.is_household_member(household_id))
WITH CHECK (private.is_household_member(household_id));

CREATE POLICY transaction_categories_member_all
ON public.transaction_categories
FOR ALL TO authenticated
USING (private.is_household_member(household_id))
WITH CHECK (private.is_household_member(household_id));

CREATE POLICY financial_accounts_member_all
ON public.financial_accounts
FOR ALL TO authenticated
USING (private.is_household_member(household_id))
WITH CHECK (
  private.is_household_member(household_id)
  AND created_by = (SELECT auth.uid())
);

CREATE POLICY transactions_member_select
ON public.transactions
FOR SELECT TO authenticated
USING (private.is_household_member(household_id));

CREATE POLICY transactions_member_insert_draft
ON public.transactions
FOR INSERT TO authenticated
WITH CHECK (
  private.is_household_member(household_id)
  AND status = 'draft'
  AND created_by = (SELECT auth.uid())
);

CREATE POLICY transactions_member_update_draft
ON public.transactions
FOR UPDATE TO authenticated
USING (
  private.is_household_member(household_id)
  AND status = 'draft'
)
WITH CHECK (
  private.is_household_member(household_id)
  AND status IN ('draft', 'posted', 'voided')
);

CREATE POLICY transactions_member_delete_draft
ON public.transactions
FOR DELETE TO authenticated
USING (
  private.is_household_member(household_id)
  AND status = 'draft'
);

CREATE POLICY journal_entries_member_select
ON public.journal_entries
FOR SELECT TO authenticated
USING (private.is_household_member(household_id));

CREATE POLICY journal_entries_member_insert_draft
ON public.journal_entries
FOR INSERT TO authenticated
WITH CHECK (
  private.is_household_member(household_id)
  AND status = 'draft'
  AND EXISTS (
    SELECT 1
    FROM public.transactions AS t
    WHERE t.household_id = journal_entries.household_id
      AND t.id = journal_entries.transaction_id
      AND t.status = 'draft'
  )
);

